// Drizzle declarations own the physical schema. Historical SQL remains immutable.
import { sql } from "drizzle-orm";
import {
	pgTable,
	uuid,
	text,
	integer,
	boolean,
	date,
	time,
	timestamp,
	numeric,
	jsonb,
	inet,
	customType,
	primaryKey,
	unique,
	uniqueIndex,
	index,
	foreignKey,
	check,
	type PgTableExtraConfigValue,
} from "drizzle-orm/pg-core";

// PostgreSQL int8 stays a decimal string throughout the application.
const int64 = customType<{ data: string; driverData: string }>({ dataType: () => "bigint" });
const vector = customType<{ data: string; driverData: string }>({ dataType: () => "vector" });

export const auth_user = pgTable(
	"auth_user",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		created_at: timestamp("created_at", { withTimezone: true, mode: "date" })
			.notNull()
			.default(sql`now()`),
		updated_at: timestamp("updated_at", { withTimezone: true, mode: "date" })
			.notNull()
			.default(sql`now()`),
		email: text("email").notNull(),
		email_verified: boolean("email_verified").notNull(),
		name: text("name").notNull(),
		image: text("image"),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "auth_user_pkey", columns: [t.id] }),
		unique("auth_user_uq_1").on(t.email),
		check("auth_user_email_check", sql`email = lower(btrim(email))`),
	],
);

export const auth_account = pgTable(
	"auth_account",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		created_at: timestamp("created_at", { withTimezone: true, mode: "date" })
			.notNull()
			.default(sql`now()`),
		updated_at: timestamp("updated_at", { withTimezone: true, mode: "date" })
			.notNull()
			.default(sql`now()`),
		user_id: uuid("user_id").notNull(),
		provider_id: text("provider_id").notNull(),
		provider_account_id: text("provider_account_id").notNull(),
		password_hash: text("password_hash"),
		access_token: text("access_token"),
		refresh_token: text("refresh_token"),
		id_token: text("id_token"),
		access_token_expires_at: timestamp("access_token_expires_at", { withTimezone: true, mode: "date" }),
		refresh_token_expires_at: timestamp("refresh_token_expires_at", { withTimezone: true, mode: "date" }),
		provider_scope: text("provider_scope"),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "auth_account_pkey", columns: [t.id] }),
		unique("auth_account_uq_1").on(t.provider_id, t.provider_account_id),
		foreignKey({ name: "auth_account_fk_0", columns: [t.user_id], foreignColumns: [auth_user.id] }).onDelete(
			"restrict",
		),
		index("auth_account_ref_0").on(t.user_id),
	],
);

