export const account = pgTable(
	"account",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		auth_user_id: uuid("auth_user_id").notNull(),
		registration_state: text("registration_state", { enum: ["pending_domain", "active"] }).notNull(),
		registration_kind: text("registration_kind", {
			enum: ["planter", "sending_church", "network", "discovery"],
		}).notNull(),
		registration_digest: text("registration_digest"),
		personal_timezone: text("personal_timezone"),
		avatar_object_id: uuid("avatar_object_id"),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "account_pkey", columns: [t.id] }),
		unique("account_uq_0").on(t.auth_user_id),
		check("account_ck_0", sql`revision >= 1`),
		check("account_ck_1", sql`registration_state in ('pending_domain', 'active')`),
		check("account_ck_2", sql`registration_kind in ('planter', 'sending_church', 'network', 'discovery')`),
		check("account_ck_3", sql`id <> '00000000-0000-0000-0000-000000000000'::uuid`),
		foreignKey({ name: "account_fk_0", columns: [t.auth_user_id], foreignColumns: [auth_user.id] }).onDelete(
			"restrict",
		),
		foreignKey({
			name: "account_fk_1",
			columns: [t.avatar_object_id, t.id],
			foreignColumns: [file_object.id, file_object.tenant_id],
		}).onDelete("restrict"),
		index("account_ref_1").on(t.avatar_object_id, t.id),
		foreignKey({ name: "account_fk_2", columns: [t.id], foreignColumns: [tenant.id] }).onDelete("restrict"),
		foreignKey({ name: "account_fk_3", columns: [t.id], foreignColumns: [record.id] }).onDelete("restrict"),
	],
);

export const admission_attempt = pgTable(
	"admission_attempt",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		kind: text("kind", {
			enum: ["login", "password_change", "registration", "reset", "email_change", "seat_invite", "relationship_invite"],
		}).notNull(),
		identifier_hash: text("identifier_hash"),
		trusted_ip_hash: text("trusted_ip_hash"),
		workspace_key: text("workspace_key"),
		reserved_at: timestamp("reserved_at", { withTimezone: true, mode: "date" }).notNull(),
		state: text("state", { enum: ["reserved", "failed", "counted", "cleared"] }).notNull(),
		expires_at: timestamp("expires_at", { withTimezone: true, mode: "date" }).notNull(),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "admission_attempt_pkey", columns: [t.id] }),
		check(
			"admission_attempt_ck_0",
			sql`kind in ('login', 'password_change', 'registration', 'reset', 'email_change', 'seat_invite', 'relationship_invite')`,
		),
		check("admission_attempt_ck_1", sql`state in ('reserved', 'failed', 'counted', 'cleared')`),
		check("admission_attempt_ck_2", sql`num_nonnulls(identifier_hash, trusted_ip_hash, workspace_key) >= 1`),
		check("admission_attempt_ck_3", sql`expires_at > reserved_at`),
	],
);

export const identity_proof = pgTable(
	"identity_proof",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		account_id: uuid("account_id").notNull(),
		purpose: text("purpose", { enum: ["email_change", "deletion_cancel"] }).notNull(),
		token_hash: text("token_hash").notNull(),
		proposed_email: text("proposed_email"),
		deletion_subject_id: uuid("deletion_subject_id"),
		request_revision: integer("request_revision"),
		expires_at: timestamp("expires_at", { withTimezone: true, mode: "date" }).notNull(),
		consumed_at: timestamp("consumed_at", { withTimezone: true, mode: "date" }),
		superseded_at: timestamp("superseded_at", { withTimezone: true, mode: "date" }),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "identity_proof_pkey", columns: [t.id] }),
		unique("identity_proof_uq_0").on(t.id, t.account_id),
		unique("identity_proof_uq_1").on(t.token_hash),
		uniqueIndex("identity_proof_uq_2")
			.on(t.account_id, t.purpose)
			.where(sql`consumed_at is null and superseded_at is null`),
		check("identity_proof_ck_0", sql`purpose in ('email_change', 'deletion_cancel')`),
		check("identity_proof_ck_1", sql`(purpose = 'email_change') = (proposed_email is not null)`),
		check("identity_proof_ck_2", sql`(purpose = 'deletion_cancel') = (deletion_subject_id is not null)`),
		foreignKey({ name: "identity_proof_fk_0", columns: [t.account_id], foreignColumns: [account.id] }).onDelete(
			"restrict",
		),
		foreignKey({
			name: "identity_proof_fk_1",
			columns: [t.deletion_subject_id],
			foreignColumns: [lifecycle_witness.id],
		}).onDelete("restrict"),
		index("identity_proof_ref_1").on(t.deletion_subject_id),
	],
);

export const plant = pgTable(
	"plant",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		name: text("name").notNull(),
		street: text("street"),
		description: text("description"),
		timezone: text("timezone").notNull(),
		warning_days: integer("warning_days").notNull(),
		alert_days: integer("alert_days").notNull(),
		digest_weekday: integer("digest_weekday").notNull(),
		digest_hour: integer("digest_hour").notNull(),
		phase: integer("phase").notNull(),
		material_revision: int64("material_revision").notNull(),
		lead_answer: text("lead_answer", { enum: ["yes", "no", "skip"] }),
		journey_answer: text("journey_answer", { enum: ["existing", "unsure", "discerning", "skip"] }),
		launch_answer: text("launch_answer", { enum: ["planned", "no_date", "skip"] }),
		onboarding_completed_at: timestamp("onboarding_completed_at", { withTimezone: true, mode: "date" }),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "plant_pkey", columns: [t.id] }),
		check("plant_ck_0", sql`revision >= 1`),
		check("plant_ck_1", sql`length(btrim(name)) > 0`),
		check("plant_ck_2", sql`warning_days between 1 and 365`),
		check("plant_ck_3", sql`alert_days between 1 and 365`),
		check("plant_ck_4", sql`warning_days < alert_days`),
		check("plant_ck_5", sql`digest_weekday between 0 and 6`),
		check("plant_ck_6", sql`digest_hour between 0 and 23`),
		check("plant_ck_7", sql`phase between 0 and 6`),
		check("plant_ck_8", sql`lead_answer in ('yes', 'no', 'skip')`),
		check("plant_ck_9", sql`journey_answer in ('existing', 'unsure', 'discerning', 'skip')`),
		check("plant_ck_10", sql`launch_answer in ('planned', 'no_date', 'skip')`),
		check("plant_ck_11", sql`id <> '00000000-0000-0000-0000-000000000000'::uuid`),
		foreignKey({ name: "plant_fk_0", columns: [t.id], foreignColumns: [tenant.id] }).onDelete("restrict"),
		foreignKey({ name: "plant_fk_1", columns: [t.id], foreignColumns: [record.id] }).onDelete("restrict"),
	],
);

