export const discovery = pgTable(
	"discovery",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		account_id: uuid("account_id").notNull(),
		lead_answer: text("lead_answer", { enum: ["yes", "no", "skip"] }),
		journey_answer: text("journey_answer", { enum: ["existing", "unsure", "discerning", "skip"] }),
		launch_answer: text("launch_answer", { enum: ["planned", "no_date", "skip"] }),
		converted_plant_id: uuid("converted_plant_id"),
		converted_at: timestamp("converted_at", { withTimezone: true, mode: "date" }),
		conversion_operation_id: uuid("conversion_operation_id"),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "discovery_pkey", columns: [t.id] }),
		unique("discovery_uq_0").on(t.id, t.account_id),
		unique("discovery_uq_1").on(t.account_id),
		check("discovery_ck_0", sql`revision >= 1`),
		check("discovery_ck_1", sql`(converted_at is null) = (converted_plant_id is null)`),
		check("discovery_ck_2", sql`lead_answer in ('yes', 'no', 'skip')`),
		check("discovery_ck_3", sql`journey_answer in ('existing', 'unsure', 'discerning', 'skip')`),
		check("discovery_ck_4", sql`launch_answer in ('planned', 'no_date', 'skip')`),
		foreignKey({ name: "discovery_fk_0", columns: [t.account_id], foreignColumns: [account.id] }).onDelete("restrict"),
		foreignKey({ name: "discovery_fk_1", columns: [t.converted_plant_id], foreignColumns: [plant.id] }).onDelete(
			"restrict",
		),
		index("discovery_ref_1").on(t.converted_plant_id),
		foreignKey({
			name: "discovery_fk_2",
			columns: [t.conversion_operation_id],
			foreignColumns: [operation.id],
		}).onDelete("restrict"),
		index("discovery_ref_2").on(t.conversion_operation_id),
		foreignKey({
			name: "discovery_fk_3",
			columns: [t.id, t.account_id],
			foreignColumns: [record.id, record.tenant_id],
		}).onDelete("restrict"),
	],
);

export const seat = pgTable(
	"seat",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		account_id: uuid("account_id").notNull(),
		plant_id: uuid("plant_id"),
		organization_id: uuid("organization_id"),
		role: text("role", { enum: ["owner", "admin", "member"] }).notNull(),
		accepted_at: timestamp("accepted_at", { withTimezone: true, mode: "date" }).notNull(),
		ended_at: timestamp("ended_at", { withTimezone: true, mode: "date" }),
		invitation_id: uuid("invitation_id"),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "seat_pkey", columns: [t.id] }),
		uniqueIndex("seat_uq_0")
			.on(t.account_id)
			.where(sql`ended_at is null`),
		uniqueIndex("seat_uq_1")
			.on(t.plant_id)
			.where(sql`role = 'owner' and ended_at is null`),
		uniqueIndex("seat_uq_2")
			.on(t.organization_id)
			.where(sql`role = 'owner' and ended_at is null`),
		check("seat_ck_0", sql`revision >= 1`),
		check("seat_ck_1", sql`role in ('owner', 'admin', 'member')`),
		check("seat_ck_2", sql`num_nonnulls(plant_id, organization_id) = 1`),
		foreignKey({ name: "seat_fk_0", columns: [t.account_id], foreignColumns: [account.id] }).onDelete("restrict"),
		foreignKey({ name: "seat_fk_1", columns: [t.plant_id], foreignColumns: [plant.id] }).onDelete("restrict"),
		foreignKey({ name: "seat_fk_2", columns: [t.organization_id], foreignColumns: [organization.id] }).onDelete(
			"restrict",
		),
		foreignKey({ name: "seat_fk_3", columns: [t.invitation_id], foreignColumns: [invitation.id] }).onDelete("restrict"),
		index("seat_ref_3").on(t.invitation_id),
		foreignKey({ name: "seat_fk_4", columns: [t.id], foreignColumns: [record.id] }).onDelete("restrict"),
	],
);

