export const attestation = pgTable(
	"attestation",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		plant_id: uuid("plant_id").notNull(),
		key: text("key", {
			enum: [
				"values_documented",
				"financial_base_established",
				"core_group_giving",
				"prayer_leader_assigned",
				"prayer_rhythm_established",
				"prayer_in_gatherings",
				"systems_tested",
				"worship_agreement",
				"community",
				"promotion_plan",
				"relationship",
				"leadership_candidate",
			],
		}).notNull(),
		reference_version_id: uuid("reference_version_id").notNull(),
		person_id: uuid("person_id"),
		state: text("state", { enum: ["answered", "unanswered", "retracted"] }).notNull(),
		answer: boolean("answer"),
		as_of: date("as_of", { mode: "string" }).notNull(),
		attested_at: timestamp("attested_at", { withTimezone: true, mode: "date" }).notNull(),
		period_start: date("period_start", { mode: "string" }),
		period_end: date("period_end", { mode: "string" }),
		attendance_continuous: boolean("attendance_continuous"),
		volunteering_continuous: boolean("volunteering_continuous"),
		statement: text("statement"),
		source_description: text("source_description"),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "attestation_pkey", columns: [t.id] }),
		unique("attestation_uq_0").on(t.id, t.plant_id),
		uniqueIndex("attestation_uq_1")
			.on(t.plant_id, t.key)
			.where(sql`person_id is null`),
		uniqueIndex("attestation_uq_2")
			.on(t.plant_id, t.key, t.person_id)
			.where(sql`person_id is not null`),
		check("attestation_ck_0", sql`revision >= 1`),
		check(
			"attestation_ck_1",
			sql`key in ('values_documented', 'financial_base_established', 'core_group_giving', 'prayer_leader_assigned', 'prayer_rhythm_established', 'prayer_in_gatherings', 'systems_tested', 'worship_agreement', 'community', 'promotion_plan', 'relationship', 'leadership_candidate')`,
		),
		check("attestation_ck_2", sql`state in ('answered', 'unanswered', 'retracted')`),
		check(
			"attestation_ck_3",
			sql`key <> 'leadership_candidate' or (person_id is not null and period_start is not null and period_end is not null and attendance_continuous is not null and volunteering_continuous is not null)`,
		),
		check("attestation_ck_4", sql`period_end is null or period_start <= period_end`),
		check(
			"attestation_ck_5",
			sql`key not in ('values_documented','financial_base_established','core_group_giving','prayer_leader_assigned','prayer_rhythm_established','prayer_in_gatherings','systems_tested') or ((state = 'answered' and answer is not null) or (state in ('unanswered','retracted') and answer is null))`,
		),
		foreignKey({ name: "attestation_fk_0", columns: [t.plant_id], foreignColumns: [plant.id] }).onDelete("restrict"),
		foreignKey({
			name: "attestation_fk_1",
			columns: [t.reference_version_id],
			foreignColumns: [reference_version.id],
		}).onDelete("restrict"),
		index("attestation_ref_1").on(t.reference_version_id),
		foreignKey({
			name: "attestation_fk_2",
			columns: [t.person_id, t.plant_id],
			foreignColumns: [person.id, person.tenant_id],
		}).onDelete("restrict"),
		index("attestation_ref_2").on(t.person_id, t.plant_id),
		foreignKey({
			name: "attestation_fk_3",
			columns: [t.id, t.plant_id],
			foreignColumns: [record.id, record.tenant_id],
		}).onDelete("restrict"),
	],
);

