export const conversation_entry = pgTable(
	"conversation_entry",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		tenant_id: uuid("tenant_id").notNull(),
		conversation_id: uuid("conversation_id").notNull(),
		sequence: int64("sequence").notNull(),
		request_key: text("request_key"),
		kind: text("kind", {
			enum: ["message", "read", "clarification", "review", "progress", "receipt", "boundary", "summary", "attachment"],
		}).notNull(),
		role: text("role", { enum: ["user", "assistant"] }),
		body: text("body"),
		display_payload: jsonb("display_payload"),
		occurred_at: timestamp("occurred_at", { withTimezone: true, mode: "date" }).notNull(),
		recorded_at: timestamp("recorded_at", { withTimezone: true, mode: "date" }).notNull(),
		object_id: uuid("object_id"),
		expires_at: timestamp("expires_at", { withTimezone: true, mode: "date" }),
		review_id: uuid("review_id"),
		operation_id: uuid("operation_id"),
		state: text("state", { enum: ["bound", "claimed", "failed", "staged"] }),
		bound_effect_id: uuid("bound_effect_id"),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "conversation_entry_pkey", columns: [t.id] }),
		unique("conversation_entry_uq_0").on(t.conversation_id, t.sequence),
		uniqueIndex("conversation_entry_uq_1")
			.on(t.conversation_id, t.request_key)
			.where(sql`request_key is not null`),
		unique("conversation_entry_uq_2").on(t.id, t.tenant_id),
		check(
			"conversation_entry_ck_0",
			sql`kind in ('message', 'read', 'clarification', 'review', 'progress', 'receipt', 'boundary', 'summary', 'attachment')`,
		),
		check("conversation_entry_ck_1", sql`role in ('user', 'assistant')`),
		check("conversation_entry_ck_2", sql`(kind = 'message') = (role is not null)`),
		check("conversation_entry_ck_3", sql`state in ('bound', 'claimed', 'failed', 'staged')`),
		check(
			"conversation_entry_ck_4",
			sql`(kind = 'attachment' and object_id is not null and operation_id is not null and state is not null and expires_at is null) or (kind <> 'attachment' and state is null and bound_effect_id is null)`,
		),
		check("conversation_entry_ck_5", sql`state <> 'bound' or bound_effect_id is not null`),
		check("conversation_entry_ck_6", sql`tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid`),
		foreignKey({ name: "conversation_entry_fk_0", columns: [t.tenant_id], foreignColumns: [tenant.id] }).onDelete(
			"restrict",
		),
		index("conversation_entry_ref_0").on(t.tenant_id),
		foreignKey({
			name: "conversation_entry_fk_1",
			columns: [t.conversation_id, t.tenant_id],
			foreignColumns: [conversation.id, conversation.tenant_id],
		}).onDelete("restrict"),
		index("conversation_entry_ref_1").on(t.conversation_id, t.tenant_id),
		foreignKey({
			name: "conversation_entry_fk_2",
			columns: [t.object_id, t.tenant_id],
			foreignColumns: [file_object.id, file_object.tenant_id],
		}).onDelete("restrict"),
		index("conversation_entry_ref_2").on(t.object_id, t.tenant_id),
		foreignKey({
			name: "conversation_entry_fk_3",
			columns: [t.review_id, t.tenant_id],
			foreignColumns: [review.id, review.tenant_id],
		}).onDelete("restrict"),
		index("conversation_entry_ref_3").on(t.review_id, t.tenant_id),
		foreignKey({
			name: "conversation_entry_fk_4",
			columns: [t.operation_id, t.tenant_id],
			foreignColumns: [operation.id, operation.tenant_id],
		}).onDelete("restrict"),
		index("conversation_entry_ref_4").on(t.operation_id, t.tenant_id),
		foreignKey({
			name: "conversation_entry_fk_5",
			columns: [t.id, t.tenant_id],
			foreignColumns: [record.id, record.tenant_id],
		}).onDelete("restrict"),
		foreignKey({
			name: "conversation_entry_fk_6",
			columns: [t.bound_effect_id, t.tenant_id],
			foreignColumns: [effect.id, effect.tenant_id],
		}).onDelete("restrict"),
		index("conversation_entry_ref_6").on(t.bound_effect_id, t.tenant_id),
	],
);

