export const effect_dependency = pgTable(
	"effect_dependency",
	{
		effect_id: uuid("effect_id").notNull(),
		tenant_id: uuid("tenant_id").notNull(),
		prerequisite_id: uuid("prerequisite_id").notNull(),
		output_key: text("output_key"),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "effect_dependency_pkey", columns: [t.effect_id, t.prerequisite_id] }),
		check("effect_dependency_ck_0", sql`effect_id <> prerequisite_id`),
		foreignKey({ name: "effect_dependency_fk_0", columns: [t.tenant_id], foreignColumns: [tenant.id] }).onDelete(
			"restrict",
		),
		index("effect_dependency_ref_0").on(t.tenant_id),
		foreignKey({
			name: "effect_dependency_fk_1",
			columns: [t.effect_id, t.tenant_id],
			foreignColumns: [effect.id, effect.tenant_id],
		}).onDelete("restrict"),
		index("effect_dependency_ref_1").on(t.effect_id, t.tenant_id),
		foreignKey({
			name: "effect_dependency_fk_2",
			columns: [t.prerequisite_id, t.tenant_id],
			foreignColumns: [effect.id, effect.tenant_id],
		}).onDelete("restrict"),
		index("effect_dependency_ref_2").on(t.prerequisite_id, t.tenant_id),
	],
);

