export const job = pgTable(
	"job",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		tenant_id: uuid("tenant_id").notNull(),
		kind: text("kind", {
			enum: [
				"mail",
				"notification",
				"digest",
				"assessment",
				"reference_generation",
				"feedback_publication",
				"object_cleanup",
				"lifecycle_purge",
				"assistant_turn",
				"document_render",
			],
		}).notNull(),
		subject_record_id: uuid("subject_record_id"),
		producer_key: text("producer_key").notNull(),
		source_revision: int64("source_revision"),
		state: text("state", {
			enum: ["ready", "claimed", "retry_wait", "reconcile", "succeeded", "failed", "cancelled", "superseded"],
		}).notNull(),
		eligible_at: timestamp("eligible_at", { withTimezone: true, mode: "date" }).notNull(),
		attempt_count: integer("attempt_count").notNull(),
		max_attempts: integer("max_attempts").notNull(),
		lease_owner: text("lease_owner"),
		lease_until: timestamp("lease_until", { withTimezone: true, mode: "date" }),
		claim_generation: int64("claim_generation").notNull(),
		checkpoint_key: text("checkpoint_key"),
		next_attempt_at: timestamp("next_attempt_at", { withTimezone: true, mode: "date" }),
		error_code: text("error_code"),
		finished_at: timestamp("finished_at", { withTimezone: true, mode: "date" }),
		revision: int64("revision")
			.notNull()
			.default(sql`1`),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "job_pkey", columns: [t.id] }),
		unique("job_uq_0").on(t.kind, t.subject_record_id, t.producer_key),
		uniqueIndex("job_uq_1")
			.on(t.tenant_id, t.kind)
			.where(sql`producer_key = 'sweep'`),
		unique("job_uq_2").on(t.id, t.tenant_id),
		check("job_ck_0", sql`revision >= 1`),
		check(
			"job_ck_1",
			sql`kind in ('mail', 'notification', 'digest', 'assessment', 'reference_generation', 'feedback_publication', 'object_cleanup', 'lifecycle_purge', 'assistant_turn', 'document_render')`,
		),
		check(
			"job_ck_2",
			sql`state in ('ready', 'claimed', 'retry_wait', 'reconcile', 'succeeded', 'failed', 'cancelled', 'superseded')`,
		),
		check("job_ck_3", sql`attempt_count >= 0 and max_attempts >= 1`),
		check("job_ck_4", sql`claim_generation >= 0`),
		check("job_ck_5", sql`(lease_owner is null) = (lease_until is null)`),
		check("job_ck_6", sql`subject_record_id is not null or producer_key = 'sweep'`),
		check(
			"job_ck_7",
			sql`tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid or kind in ('mail', 'reference_generation', 'feedback_publication', 'object_cleanup', 'lifecycle_purge')`,
		),
		foreignKey({ name: "job_fk_0", columns: [t.tenant_id], foreignColumns: [tenant.id] }).onDelete("restrict"),
		foreignKey({ name: "job_fk_1", columns: [t.subject_record_id], foreignColumns: [record.id] }).onDelete("restrict"),
		index("job_ref_1").on(t.subject_record_id),
		foreignKey({
			name: "job_fk_2",
			columns: [t.id, t.tenant_id],
			foreignColumns: [record.id, record.tenant_id],
		}).onDelete("restrict"),
	],
);

export const feedback = pgTable(
	"feedback",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		account_id: uuid("account_id").notNull(),
		plant_context_id: uuid("plant_context_id"),
		category: text("category", { enum: ["bug", "suggestion", "question", "other"] }).notNull(),
		description: text("description").notNull(),
		route_label: text("route_label"),
		submitted_at: timestamp("submitted_at", { withTimezone: true, mode: "date" }).notNull(),
		request_key: text("request_key").notNull(),
		triage_state: text("triage_state", { enum: ["new", "reviewed", "resolved", "dismissed"] }).notNull(),
		revision_number: int64("revision_number").notNull(),
		page_label: text("page_label"),
		page_address: text("page_address"),
		church_label: text("church_label"),
		role_label: text("role_label"),
		browser: text("browser"),
		screen_width: integer("screen_width"),
		screen_height: integer("screen_height"),
		theme: text("theme", { enum: ["light", "dark"] }),
		app_version: text("app_version"),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "feedback_pkey", columns: [t.id] }),
		unique("feedback_uq_0").on(t.id, t.account_id),
		unique("feedback_uq_1").on(t.account_id, t.request_key),
		check("feedback_ck_0", sql`category in ('bug', 'suggestion', 'question', 'other')`),
		check("feedback_ck_1", sql`triage_state in ('new', 'reviewed', 'resolved', 'dismissed')`),
		check("feedback_ck_2", sql`length(btrim(description)) between 1 and 5000`),
		check("feedback_ck_3", sql`route_label is null or length(route_label) <= 500`),
		check("feedback_ck_4", sql`page_label is null or length(page_label) <= 500`),
		check("feedback_ck_5", sql`page_address is null or length(page_address) <= 500`),
		check("feedback_ck_6", sql`church_label is null or length(church_label) <= 200`),
		check("feedback_ck_7", sql`role_label is null or length(role_label) <= 200`),
		check("feedback_ck_8", sql`browser is null or length(browser) <= 500`),
		check("feedback_ck_9", sql`app_version is null or length(app_version) <= 100`),
		check(
			"feedback_ck_10",
			sql`page_address is null or (page_address like '/%' and position('?' in page_address) = 0 and position('#' in page_address) = 0)`,
		),
		check("feedback_ck_11", sql`theme is null or theme in ('light', 'dark')`),
		check("feedback_ck_12", sql`screen_width is null or screen_width between 1 and 100000`),
		check("feedback_ck_13", sql`screen_height is null or screen_height between 1 and 100000`),
		foreignKey({ name: "feedback_fk_0", columns: [t.account_id], foreignColumns: [account.id] }).onDelete("restrict"),
		foreignKey({ name: "feedback_fk_1", columns: [t.plant_context_id], foreignColumns: [plant.id] }).onDelete(
			"restrict",
		),
		index("feedback_ref_1").on(t.plant_context_id),
		foreignKey({
			name: "feedback_fk_2",
			columns: [t.id, t.account_id],
			foreignColumns: [record.id, record.tenant_id],
		}).onDelete("restrict"),
	],
);

