export const lifecycle_witness = pgTable(
	"lifecycle_witness",
	{
		id: uuid("id")
			.notNull()
			.default(sql`gen_random_uuid()`),
		kind: text("kind", { enum: ["account", "plant", "seat", "affiliation"] }).notNull(),
		opaque_subject_id: uuid("opaque_subject_id").notNull(),
		account_id: uuid("account_id"),
		plant_id: uuid("plant_id"),
		request_id: uuid("request_id"),
		requester_id: uuid("requester_id"),
		request_revision: int64("request_revision").notNull(),
		state: text("state", {
			enum: ["active", "pending_deletion", "purging", "purged", "cancelled", "revoked"],
		}).notNull(),
		requested_at: timestamp("requested_at", { withTimezone: true, mode: "date" }),
		live_purged_at: timestamp("live_purged_at", { withTimezone: true, mode: "date" }),
		copy_expires_at: timestamp("copy_expires_at", { withTimezone: true, mode: "date" }),
		witness_checkpoint: int64("witness_checkpoint").notNull(),
		byte_manifest_hash: text("byte_manifest_hash"),
		cancellation_manifest_hash: text("cancellation_manifest_hash"),
		cleanup_state: text("cleanup_state", {
			enum: ["not_started", "in_progress", "inaccessible", "confirmed"],
		}).notNull(),
		seat_id: uuid("seat_id"),
		affiliation_id: uuid("affiliation_id"),
		requester_opaque_id: uuid("requester_opaque_id"),
		counterparty_organization_id: uuid("counterparty_organization_id"),
		cancel_until: timestamp("cancel_until", { withTimezone: true, mode: "date" }),
		cancelled_at: timestamp("cancelled_at", { withTimezone: true, mode: "date" }),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "lifecycle_witness_pkey", columns: [t.id] }),
		unique("lifecycle_witness_uq_0").on(t.kind, t.opaque_subject_id),
		check("lifecycle_witness_ck_0", sql`cleanup_state in ('not_started', 'in_progress', 'inaccessible', 'confirmed')`),
		check("lifecycle_witness_ck_1", sql`plant_id is null or kind = 'plant'`),
		check(
			"lifecycle_witness_ck_2",
			sql`copy_expires_at is null or copy_expires_at <= live_purged_at + interval '168 hours'`,
		),
		check("lifecycle_witness_ck_3", sql`kind in ('account', 'plant', 'seat', 'affiliation')`),
		check(
			"lifecycle_witness_ck_4",
			sql`state in ('active', 'pending_deletion', 'purging', 'purged', 'cancelled', 'revoked')`,
		),
		check("lifecycle_witness_ck_5", sql`num_nonnulls(account_id,plant_id,seat_id,affiliation_id) <= 1`),
		check("lifecycle_witness_ck_6", sql`account_id is null or kind in ('account')`),
		check("lifecycle_witness_ck_7", sql`seat_id is null or kind = 'seat'`),
		check("lifecycle_witness_ck_8", sql`affiliation_id is null or kind = 'affiliation'`),
		check(
			"lifecycle_witness_ck_9",
			sql`kind not in ('account', 'plant') or state in ('active', 'pending_deletion', 'purging', 'purged', 'cancelled')`,
		),
		check("lifecycle_witness_ck_10", sql`kind in ('account', 'plant') or state in ('active', 'revoked')`),
		check(
			"lifecycle_witness_ck_11",
			sql`state not in ('pending_deletion', 'purging', 'purged', 'cancelled') or (request_id is not null and requested_at is not null and cancel_until is not null and request_revision >= 1)`,
		),
		check(
			"lifecycle_witness_ck_12",
			sql`cancel_until is null or (requested_at is not null and cancel_until = requested_at + interval '720 hours')`,
		),
		check("lifecycle_witness_ck_13", sql`(state = 'cancelled') = (cancelled_at is not null)`),
		check(
			"lifecycle_witness_ck_14",
			sql`cancelled_at is null or (cancelled_at >= requested_at and cancelled_at < cancel_until)`,
		),
		check("lifecycle_witness_ck_15", sql`(state = 'purged') = (live_purged_at is not null)`),
		check(
			"lifecycle_witness_ck_16",
			sql`state <> 'purged' or (live_purged_at >= cancel_until and copy_expires_at is not null)`,
		),
		check(
			"lifecycle_witness_ck_17",
			sql`copy_expires_at is null or (live_purged_at is not null and copy_expires_at >= live_purged_at)`,
		),
		foreignKey({ name: "lifecycle_witness_fk_0", columns: [t.account_id], foreignColumns: [account.id] }).onDelete(
			"restrict",
		),
		index("lifecycle_witness_ref_0").on(t.account_id),
		foreignKey({ name: "lifecycle_witness_fk_1", columns: [t.plant_id], foreignColumns: [plant.id] }).onDelete(
			"restrict",
		),
		index("lifecycle_witness_ref_1").on(t.plant_id),
		foreignKey({ name: "lifecycle_witness_fk_2", columns: [t.requester_id], foreignColumns: [account.id] }).onDelete(
			"restrict",
		),
		index("lifecycle_witness_ref_2").on(t.requester_id),
		foreignKey({ name: "lifecycle_witness_fk_3", columns: [t.seat_id], foreignColumns: [seat.id] }).onDelete(
			"restrict",
		),
		index("lifecycle_witness_ref_3").on(t.seat_id),
		foreignKey({
			name: "lifecycle_witness_fk_4",
			columns: [t.affiliation_id],
			foreignColumns: [affiliation.id],
		}).onDelete("restrict"),
		index("lifecycle_witness_ref_4").on(t.affiliation_id),
		foreignKey({
			name: "lifecycle_witness_fk_5",
			columns: [t.counterparty_organization_id],
			foreignColumns: [organization.id],
		}).onDelete("restrict"),
		index("lifecycle_witness_ref_5").on(t.counterparty_organization_id),
		foreignKey({ name: "lifecycle_witness_fk_6", columns: [t.id], foreignColumns: [record.id] }).onDelete("restrict"),
	],
);

