export const tenant = pgTable(
	"tenant",
	{
		id: uuid("id").notNull(),
		kind: text("kind", { enum: ["account", "plant", "organization", "global"] }).notNull(),
	},
	(t): PgTableExtraConfigValue[] => [
		primaryKey({ name: "tenant_pkey", columns: [t.id] }),
		check("tenant_ck_0", sql`kind in ('account', 'plant', 'organization', 'global')`),
		check("tenant_ck_1", sql`(kind = 'global') = (id = '00000000-0000-0000-0000-000000000000'::uuid)`),
	],
);

